local exports = {}

local function KHBBSItemData(data)
    if data.name == nil or data.category == nil or data.code == nil then
        error("KHBBSItemData requires a name, category and code")
    end
    -- TODO: Make sure that classification, characters and max_quantity matter here
    if data.classification == nil then
        data.classification = "filler"
    end
    if data.characters == nil then
        data.characters = "TVA"
    end
    if data.max_quantity == nil then
        data.max_quantity = 1 -- Is this right? Hmm...
    end
    if data.khbbsid == nil then
        data.khbbsid = nil -- Redundant, but explicit
    end
    return data
end

